from app.models.base import *

profile = table("profile", *texts("full_name email phone location_city location_state location_country linkedin_url github_url portfolio_url headline summary_facts_note work_authorization_note notice_period_note"), field("other_links", JSONB, required=True, default="[]"), field("open_to_relocation", Boolean, required=True, default="false"), field("open_to_remote", Boolean, required=True, default="false"))
# A unique constant expression enforces the single-owner profile invariant.
from sqlalchemy import Index, literal_column
Index("profile_single_row", literal_column("(true)"), unique=True, _table=profile)
education = table("education", ref("profile_id", "profile.id"), *texts("institution degree field grade_value grade_scale location notes"), *dates("start_date end_date"), ordered())
experience = table("experience", ref("profile_id", "profile.id"), *texts("company role_title location description_raw"), choice("employment_type", "internship full_time part_time contract freelance volunteer"), *dates("start_date end_date"), ordered())
project = table("project", ref("profile_id", "profile.id"), *texts("name one_liner role problem_statement solution_overview architecture_notes challenges_and_solutions outcomes repo_url live_url demo_url paper_url"), choice("status", "shipped in_progress prototype archived"), field("team_size", Integer), *dates("start_date end_date"), *lists("domain_tags"), field("visibility_priority", Integer, required=True, default="3"), ordered(), constraints=(CheckConstraint("visibility_priority BETWEEN 1 AND 5"), CheckConstraint("team_size IS NULL OR team_size > 0")))
project_tech = table("project_tech", ref("project_id", "project.id"), field("technology", required=True), field("usage_note"), field("is_primary", Boolean, required=True, default="false"))
achievement = table("achievement", ref("profile_id", "profile.id"), *texts("title issuer_or_event rank_or_result description link_url"), *dates("date"), ordered())
publication = table("publication", ref("profile_id", "profile.id"), *texts("title venue link_url description"), *dates("date"))
certification = table("certification", ref("profile_id", "profile.id"), *texts("name issuer credential_url"), *dates("date"))
skill = table("skill", ref("profile_id", "profile.id"), field("name", required=True), *lists("aliases"), choice("category", "language framework database devops ai_ml tool concept soft"), choice("proficiency", "expert strong working familiar"), field("years_note"), field("claim_allowed", Boolean, required=True, default="true"))
resume_variant = table("resume_variant", field("name", required=True), *lists("section_order skill_group_order"), field("max_projects", Integer, required=True, default="3"), field("max_bullets_per_project", Integer, required=True, default="3"), field("max_bullets_per_experience", Integer, required=True, default="3"), field("summary_style_note"), field("is_default", Boolean, required=True, default="false"), constraints=(CheckConstraint("max_projects > 0 AND max_bullets_per_project > 0 AND max_bullets_per_experience > 0"),))
fact = table("fact", choice("parent_type", "project experience achievement education publication certification skill profile"), field("parent_id", UUID(as_uuid=True), required=True), field("text", required=True), choice("fact_type", "action outcome metric scope technology_usage responsibility recognition"), field("numeric_values", JSONB, required=True, default="[]"), *lists("technologies"), field("is_verified_by_user", Boolean, required=True, default="false"), choice("source", "user_typed derived_from_description"), ref("superseded_by", "fact.id", required=False))
